-- UPDATE and DELETE conditions with subqueries that read the target row, the
-- FROM/USING items or both run them for each row.
CREATE TABLE t216 (a int, b int); CREATE TABLE f216 (a int, c int);
INSERT INTO t216 VALUES (1, 1), (2, 2); INSERT INTO f216 VALUES (1, 5), (2, 6);
DELETE FROM t216 USING f216 WHERE t216.a = f216.a AND f216.c = (SELECT max(c) FROM f216 WHERE f216.a = t216.a) RETURNING t216.a;
DELETE FROM t216 USING f216 WHERE t216.a = f216.a AND EXISTS (SELECT 1 FROM f216 g216 WHERE g216.a = t216.a);
UPDATE t216 SET b = 9 FROM f216 WHERE f216.c = (SELECT max(c) FROM f216 WHERE f216.a = t216.a);
DELETE FROM t216 WHERE b = (SELECT max(c) FROM f216 WHERE f216.a = t216.a);
INSERT INTO t216 VALUES (1, 5), (2, 2), (3, 3);
UPDATE t216 SET b = b + 10 WHERE EXISTS (SELECT 1 FROM f216 WHERE f216.a = t216.a) RETURNING *;
UPDATE t216 SET b = 0 WHERE b > (SELECT count(*) FROM f216) AND a NOT IN (SELECT a FROM f216 WHERE f216.c < t216.b) RETURNING *;
DELETE FROM t216 WHERE a IN (SELECT a FROM f216 WHERE f216.c > t216.b) RETURNING *;
DELETE FROM t216 WHERE (SELECT t216.a) = 3 RETURNING *;
SELECT * FROM t216 ORDER BY a;
DROP TABLE t216, f216;
